166: pub fn calc_crc32(data: &[u8]) -> u32 {
167:     let mut crc = 0xFFFF_FFFFu32;
168:     for &b in data {
169:         let idx = ((crc ^ (b as u32)) & 0xFF) as usize;
170:         crc = (crc >> 8) ^ CRC32_TABLE[idx];
