119: fn test_corrupted_frame_candidate_rejections() {
120:     // 1. Bad magic byte != 0x55
121:     for &bad_magic in &[0x00u8, 0x54, 0x56, 0xAA, 0xFF] {
122:         let frame = [
123:             bad_magic, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
124:         ];
125:         assert_eq!(
126:             DatFrame::parse(&frame),
127:             Err(FlightReaderError::SyncNotFound),
128:             "Failed for bad magic 0x{:02X}",
129:             bad_magic
130:         );
131:     }
132: 
133:     // 2. Buffer too short for magic or header length
134:     assert_eq!(DatFrame::parse(&[]), Err(FlightReaderError::UnexpectedEof));
135:     assert_eq!(
136:         DatFrame::parse(&[0x55]),
137:         Err(FlightReaderError::UnexpectedEof)
138:     );
139: 
140:     // 3. Length field under minimum allowable size (< 11)
141:     for &bad_len in &[0u8, 1, 5, 8, 9, 10] {
142:         let frame = [
143:             0x55, bad_len, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
144:         ];
145:         assert_eq!(
146:             DatFrame::parse(&frame),
147:             Err(FlightReaderError::InvalidFrameLength {
148:                 length: bad_len,
149:                 minimum: 11
150:             }),
151:             "Failed for bad length {}",
152:             bad_len
153:         );
154:     }
155: 
156:     // 4. Truncated payload: buffer length < declared length
157:     let truncated_frame = [
158:         0x55, 0x1B, 0x2A, 0x01, 0x00, 0x4E, 0x61, 0xBC, 0x00, 0x10, 0x20,
159:     ]; // Declares 27 bytes (0x1B), but only 11 bytes present
160:     assert_eq!(
161:         DatFrame::parse(&truncated_frame),
162:         Err(FlightReaderError::TruncatedRecord {
163:             expected: 27,
164:             available: 11
165:         })
166:     );
167: 
168:     // 5. Checksum mismatch in CRC16 frame (payload bit flip)
169:     let mut bit_flip_frame = [
170:         0x55, 0x1B, 0x2A, 0x01, 0x00, 0x4E, 0x61, 0xBC, 0x00, 0x10, 0x20, 0x30, 0x40, 0x50, 0x60,
171:         0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x00, 0x42, 0xDA,
172:     ];
173:     bit_flip_frame[9] ^= 0x01; // Corrupt payload byte
174:     assert!(matches!(
175:         DatFrame::parse(&bit_flip_frame),
176:         Err(FlightReaderError::ChecksumMismatch { .. })
177:     ));
178: 
179:     // 6. Checksum mismatch in CRC16 frame (corrupted trailer bytes)
180:     let mut bad_trailer = [
181:         0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
182:     ];
183:     bad_trailer[9] = 0x00;
184:     bad_trailer[10] = 0x00;
185:     assert!(matches!(
186:         DatFrame::parse(&bad_trailer),
187:         Err(FlightReaderError::ChecksumMismatch { .. })
188:     ));
189: 
190:     // 7. Checksum mismatch in CRC32 frame
191:     let mut bad_crc32 = [
192:         0x55, 0x1D, 0x2C, 0x12, 0x00, 0x16, 0x62, 0xBC, 0x00, 0x10, 0x20, 0x30, 0x40, 0x50, 0x60,
193:         0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x00, 0x00, 0x00, 0x00, 0x00,
194:     ];
195:     bad_crc32[25] = 0xFF;
196:     assert!(matches!(
197:         DatFrame::parse(&bad_crc32),
198:         Err(FlightReaderError::ChecksumMismatch { .. })
199:     ));
