203: fn test_crc16_fallback_seed_support() {
204:     let mut frame = [0u8; 11];
205:     frame[0] = 0x55;
206:     frame[1] = 11;
207:     frame[2] = 0x01; // sequence
208:     frame[3] = 0x05; // payload_id LE
209:     frame[4] = 0x00;
210:     frame[5] = 0x10; // timestamp LE
211:     frame[6] = 0x20;
212:     frame[7] = 0x30;
213:     frame[8] = 0x40;
214: 
215:     // Calculate with fallback seed 0xFFFF
216:     let crc = calc_crc16_ccitt(&frame[..9], CRC16_INIT_FALLBACK);
217:     frame[9..11].copy_from_slice(&crc.to_le_bytes());
218: 
219:     // verify_crc16 should succeed using the fallback seed
220:     assert!(verify_crc16(&frame).is_ok());
221: 
222:     // DatFrame::parse should also succeed
223:     let parsed = DatFrame::parse(&frame).expect("Parsed with fallback seed");
224:     assert_eq!(parsed.payload_id, 5);
225:     assert_eq!(parsed.checksum_type, DatChecksumType::Crc16);
226: 
227:     // Direct seed verification
228:     assert!(verify_crc16_with_seed(&frame, CRC16_INIT_FALLBACK).is_ok());
229:     assert!(verify_crc16_with_seed(&frame, CRC16_INIT_PRIMARY).is_err());
230: }
