282: #[test]
283: fn test_resynchronization_with_embedded_0x55_in_payload() {
284:     // Construct a frame where the payload itself contains repeated 0x55 bytes
285:     let mut frame_bytes = vec![
286:         0x55, 17, 10, 0x01, 0x00, 0x50, 0x00, 0x00, 0x00, // Header (9B)
287:         0x55, 0x55, 0x55, 0x55, 0x55, 0x55, // Payload: 6 bytes of 0x55 (offset 9..15)
288:         0x00, 0x00, // Checksum placeholder
289:     ];
290:     let crc = calc_crc16_ccitt(&frame_bytes[..15], CRC16_INIT_PRIMARY);
291:     frame_bytes[15..17].copy_from_slice(&crc.to_le_bytes());
292: 
293:     // Wrap frame in arbitrary garbage noise before and after
294:     let mut noisy_stream = vec![0x12, 0x34, 0x55, 0x02]; // False sync at index 2
295:     noisy_stream.extend_from_slice(&frame_bytes);
296:     noisy_stream.extend_from_slice(&[0x99, 0x88, 0x55, 0x55]); // Trailing garbage
297: 
298:     let mut iter = DatFrameIterator::new(&noisy_stream);
299:     let recovered = iter
300:         .next()
301:         .expect("Should find frame")
302:         .expect("Valid frame");
303: 
304:     assert_eq!(recovered.length, 17);
305:     assert_eq!(recovered.sequence, 10);
306:     assert_eq!(recovered.payload_id, 1);
307:     assert_eq!(recovered.payload, &[0x55; 6]);
308:     assert_eq!(recovered.checksum_type, DatChecksumType::Crc16);
309: 
310:     // No further valid frames
311:     assert!(iter.next().is_none());
312: }
