23:     /// Property 1: Involutive roundtrip symmetry of cyclic XOR de-scrambling.
24:     /// Double application of the 8-byte key restores original plaintext bit-for-bit.
25:     #[test]
26:     fn prop_xor_involutive_roundtrip(
27:         payload in proptest::collection::vec(any::<u8>(), 0..2048),
28:         seed in any::<u8>(),
29:         record_type in 1u8..=57u8,
30:     ) {
