39:         // Vector double roundtrip
40:         let scrambled_vec = descramble_to_vec(&payload, key);
41:         let recovered_vec = descramble_to_vec(&scrambled_vec, key);
42:         prop_assert_eq!(&recovered_vec, &payload);
